pub fn emit_seeds_declared(first: i64, n: i64, defaulted: bool) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    let mut at = first;
    while at < first + n {
        if defaulted { out.push(format!("__S{}: nikaia_std::hash::Seed = nikaia_std::hash::Keyed", at)); } else { out.push(format!("__S{}: nikaia_std::hash::Seed", at)); }
        at += 1;
    }
    out
}

pub fn emit_seeds_applied(first: i64, n: i64) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    let mut at = first;
    while at < first + n {
        out.push(format!("__S{}", at));
        at += 1;
    }
    out
}

